MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']

def norm_dob(text):
    s = str(text or '').strip().lower()
    m = re.search(r'(\d{4})-(\d{1,2})-(\d{1,2})', s)
    if m:
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
    else:
        m = re.search(r'(\d{1,2})[./ -](\d{1,2})[./ -](\d{2,4})', s)
        if m:
            d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        else:
            mo = None
            for i, name in enumerate(MONTHS):
                if re.search(r'\b' + name[:3], s):
                    mo = i + 1
                    break
            nums = re.findall(r'\d+', s)
            y = next((int(x) for x in nums if len(x) == 4), None)
            d = next((int(x) for x in nums if len(x) <= 2), None)
            if not (mo and y and d):
                return str(text or '').strip()
    if y < 100:
        y += 1900 if y > 30 else 2000
    return '%04d-%02d-%02d' % (y, mo, d)

try:
    b = config.get('body')
    if isinstance(b, dict):
        if b.get('field') == 'date_of_birth':
            b['answer'] = norm_dob(b.get('answer'))
        elif b.get('field') == 'phone_last4':
            b['answer'] = re.sub(r'\D', '', str(b.get('answer') or ''))[-4:]
