     "code": {"type": "string", "default": "import datetime
import json

WEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']

def parse_now(value):
    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')
    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):
        try:
            return datetime.datetime.strptime(s[:size], fmt)
        except ValueError:
            pass
    raise ValueError('cannot read now: ' + s)

def parse_holidays(values):
    out = set()
    for v in values or []:
        try:
            out.add(datetime.date.fromisoformat(str(v)[:10]))
        except ValueError:
            pass
    return out

def is_business_day(d, holidays):
    return d.weekday() < 5 and d not in holidays

def next_business_day(d, holidays, include_today=False):
    if include_today and is_business_day(d, holidays):
        return d
    d = d + datetime.timedelta(days=1)
    while not is_business_day(d, holidays):
        d = d + datetime.timedelta(days=1)
    return d

def add_business_days(d, n, holidays):
    for _ in range(int(n)):
        d = next_business_day(d, holidays)
    return d

def week_monday(d):
    return d - datetime.timedelta(days=d.weekday())

def last_business_day_of_week(d, holidays):
    day = week_monday(d) + datetime.timedelta(days=4)
    while day >= week_monday(d):
        if is_business_day(day, holidays):
            return day
        day = day - datetime.timedelta(days=1)
    return None

def spoken_date(d):
    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()

def money(amount):
    v = round(float(amount), 2)
    return '{:,.0f}'.format(v) if v == int(v) else '{:,.2f}'.format(v)

def as_list(value):
    if isinstance(value, list):
        return value
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            return []
    if isinstance(value, dict):
        return [value]
    return value if isinstance(value, list) else []

def list_from_vars(vars, name, prefixes):
    found = as_list(vars.get(name)) if vars.get(name) not in (None, '') else []
    if found:
        return found
    for prefix in prefixes:
        rows = {}
        start = prefix + '.'
        for key, value in vars.items():
            if not str(key).startswith(start):
                continue
            rest = str(key)[len(start):]
            idx, _, field = rest.partition('.')
            if idx.isdigit():
                if field:
                    rows.setdefault(int(idx), {})[field] = value
                else:
                    rows[int(idx)] = value
        if rows:
            return [rows[i] for i in sorted(rows)]
        whole = vars.get(prefix)
        if whole not in (None, ''):
            got = as_list(whole)
            if got:
                return got
    return []

HOLIDAYS = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
BANDS = [('early', 1, 7, 12, 1), ('late', 8, 45, 7, 2)]
try:
    now = parse_now(vars.get('now'))
    hol = parse_holidays(HOLIDAYS)
    today = now.date()
    items = list_from_vars(vars, 'products', ['load_account_response.data.products', 'get_account_response.data.products'])
    p = items[0]
    ptype = str(p.get('type') or '')
    days = int(float(p.get('days_late') or 0))
    band = BANDS[0] if days <= 7 else BANDS[1]
    deadline = add_business_days(today, band[3], hol)
    wk = last_business_day_of_week(today, hol)
    if wk is None or wk <= today:
        wk = last_business_day_of_week(today + datetime.timedelta(days=7), hol)
    attempt1 = min(wk, deadline) if wk else deadline
    if ptype == 'credit_card':
        name = 'credit card ending ' + str(p.get('card_last4') or '')
        floor = p.get('minimum_payment')
    elif ptype == 'car_loan':
        name = 'car loan'
        floor = p.get('instalment_amount')
    else:
        name = 'personal loan'
        floor = p.get('instalment_amount')
    past_due = float(p.get('past_due') or 0)
    floor = float(floor or 0)
    if floor <= 0 or floor > past_due:
        floor = past_due
    debt = 'I am calling from the collections team about a late payment on your ' + name + '. The past-due amount is ' + money(past_due) + ', and it is ' + str(days) + ' days late.'
    vars['product_id'] = str(p.get('product_id') or '')
    vars['product_name'] = name
    vars['past_due_text'] = money(past_due)
    vars['floor_text'] = money(floor)
    vars['deadline_iso'] = deadline.isoformat()
    vars['deadline_spoken'] = spoken_date(deadline)
    vars['attempt1_iso'] = attempt1.isoformat()
    vars['band'] = band[0]
    vars['attempts_allowed'] = str(band[4])
    vars['debt_text'] = debt
    vars['floor_offer_text'] = 'I can offer a lower amount of ' + money(floor) + '. The rest stays overdue. Can you pay ' + money(floor) + '?'
    vars['attempt1_full_text'] = 'Could you pay the full ' + money(past_due) + ' by ' + spoken_date(attempt1) + '?'
    vars['attempt1_floor_text'] = 'Could you pay ' + money(floor) + ' by ' + spoken_date(attempt1) + '? The rest stays overdue.'
    vars['attempt2_text'] = 'Could you pay ' + money(floor) + ' by ' + spoken_date(deadline) + '? The rest stays overdue.' if band[4] >= 2 else ''
    rows = []
    for i in range(0, 22):
        d = today + datetime.timedelta(days=i)
        if d > deadline:
            status = 'after the deadline: say the latest date you can record is ' + spoken_date(deadline) + ' and offer it'
        elif not is_business_day(d, hol):
            alt = next_business_day(d, hol)
            status = 'not a business day: offer ' + spoken_date(alt) + ' (' + alt.isoformat() + ')' if alt <= deadline else 'not a business day, and the next business day is after the deadline: offer ' + spoken_date(deadline)
        else:
            status = 'allowed'
        rows.append('- ' + spoken_date(d) + ' (' + d.isoformat() + ')' + (' today' if i == 0 else '') + ': ' + status)
    words = []
    for w in range(7):
        this_d = week_monday(today) + datetime.timedelta(days=w)
        next_d = this_d + datetime.timedelta(days=7)
        words.append('- this ' + WEEKDAYS[w].title() + ' = ' + spoken_date(this_d) + ' (' + this_d.isoformat() + '); next ' + WEEKDAYS[w].title() + ' = ' + spoken_date(next_d) + ' (' + next_d.isoformat() + ')')
    lines = [
        'Today is ' + spoken_date(today) + ' (' + today.isoformat() + ').',
        'Product: ' + name + ' (product_id ' + vars['product_id'] + '). Past-due amount: ' + money(past_due) + '. Days late: ' + str(days) + '. Lowest amount (floor): ' + money(floor) + '.',
        'Deadline (latest promise date): ' + spoken_date(deadline) + ' (' + deadline.isoformat() + ').',
        'A promise date must be today or later, a business day, and not after the deadline. A promise amount must be from ' + money(floor) + ' to ' + money(past_due) + ', both included.',
        'Date table:',
    ] + rows + ['Weekday words (next means the following calendar week, this means the current week):'] + words + [
        'Say these sentences exactly when they apply:',
        '- The customer says the full amount is too much and the lower amount was not offered yet: "' + vars['floor_offer_text'] + '"',
