                if re.search(r'\b' + name[:3], s):
                    mo = i + 1
                    break
            nums = re.findall(r'\d+', s)
            y = next((int(x) for x in nums if len(x) == 4), None)
            d = next((int(x) for x in nums if len(x) <= 2), None)
            if not (mo and y and d):
