            amt = None
        ds = str(b.get('date') or '').strip()[:10]
        b['date'] = ds
        today = datetime.date.fromisoformat(str(vars.get('now'))[:10])
        dl = datetime.date.fromisoformat(str(vars.get('deadline_iso'))[:10])
