            d = None
        if d is None:
            msg = 'The date is not valid. Ask for the exact day.'
        elif d < today:
            msg = 'That date is in the past. A promise date must be today or later. Ask for another day.'
        elif d > dl:
            msg = 'The date is after the deadline. Say: The latest date I can record is ' + str(vars.get('deadline_spoken')) + '. Can you pay by then?'
        elif d.weekday() >= 5 or ds in HOL:
            nd = d + datetime.timedelta(days=1)
            while nd.weekday() >= 5 or nd.isoformat() in HOL:
                nd = nd + datetime.timedelta(days=1)
            msg = 'That day is not a business day. Offer ' + nd.isoformat() + ' instead and read back again.'
        elif amt is None:
            msg = 'The amount is not valid. Read back the amount again.'
        elif amt < floor - 0.001:
            msg = 'The amount is below the floor. Say: I cannot record an amount below ' + str(vars.get('floor_text')) + '. Could you pay ' + str(vars.get('floor_text')) + '?'
