        next_d = this_d + datetime.timedelta(days=7)
        words.append('- this ' + WEEKDAYS[w].title() + ' = ' + spoken_date(this_d) + ' (' + this_d.isoformat() + '); next ' + WEEKDAYS[w].title() + ' = ' + spoken_date(next_d) + ' (' + next_d.isoformat() + ')')
    lines = [
        'Today is ' + spoken_date(today) + ' (' + today.isoformat() + ').',
        'Product: ' + name + ' (product_id ' + vars['product_id'] + '). Past-due amount: ' + money(past_due) + '. Days late: ' + str(days) + '. Lowest amount (floor): ' + money(floor) + '.',
        'Deadline (latest promise date): ' + spoken_date(deadline) + ' (' + deadline.isoformat() + ').',
        'A promise date must be today or later, a business day, and not after the deadline. A promise amount must be from ' + money(floor) + ' to ' + money(past_due) + ', both included.',
